#!/usr/bin/env bun
import { join } from "node:path";
import { $ } from "bun";

const env = { ...process.env };

if (!env.DATABASE_URL) {
  env.DATABASE_URL = "postgresql://user:password@localhost:5432/postgres";
}

env.PRISMA_CONFIG_PATH = join(process.cwd(), "prisma.config.ts");

async function runGenerate(command: ReturnType<typeof $>) {
  try {
    await command;
  } catch (error) {
    if (error instanceof Error && "exitCode" in error) {
      const exitCode = Number((error as { exitCode?: number }).exitCode ?? 1);
      process.exit(exitCode);
    }

    throw error;
  }
}

await runGenerate($`prisma generate`.env(env));
